with deduped as (select * from (select *, rank() over (partition by product_id order by sale_date desc nulls last) as row_num from store_sales) t where row_num = 1) select case when revenue >= 3200 then 'HIGH' else 'LOW' end as revenue_tier, product_id, max(revenue) as max_revenue, corr(units, revenue) as corr_units_revenue, round(avg(revenue), 2) as avg_revenue, approx_percentile(revenue, 0.95) as revenue_p95, bit_and(units) as units_bit_and from deduped group by case when revenue >= 3200 then 'HIGH' else 'LOW' end, product_id having approx_percentile(revenue, 0.95) > 0 order by revenue_p95;
